# Step: scan inbox and outbox threads, compute desired label based on participant emails.

page_limit = 20

def scan_threads(category):
    desired = {}  # thread_id -> desired label (work/personal)
    current = {}  # thread_id -> current label
    page_index = 0
    while True:
        if category=='inbox':
            threads = apis.gmail.show_inbox_threads(access_token=gmail_token, page_index=page_index, page_limit=page_limit)
        else:
            threads = apis.gmail.show_outbox_threads(access_token=gmail_token, page_index=page_index, page_limit=page_limit)
        print(category, 'page', page_index, 'count', len(threads) if threads else 0)
        if not threads:
            break
        for t in threads:
            tid = t.get('email_thread_id')
            if tid is None:
                continue
            if tid not in current and 'label' in t:
                current[tid] = t.get('label')
            participants = t.get('participants') or []
            p_emails = set([p.get('email','').lower() for p in participants if p.get('email')])
            has_coworker = any(e in coworker_emails for e in p_emails)
            has_personal = any(e in personal_emails for e in p_emails)
            # priority: work overrides personal
            desired_label = None
            if has_coworker:
                desired_label = 'work'
            elif has_personal:
                desired_label = 'personal'
            if desired_label:
                if tid not in desired:
                    desired[tid] = desired_label
                else:
                    # work override
                    if desired[tid] != 'work' and desired_label=='work':
                        desired[tid] = 'work'
        page_index += 1
    return desired, current

in_desired, in_current = scan_threads('inbox')
out_desired, out_current = scan_threads('outbox')

# merge desired
all_desired = dict(in_desired)
for tid, lab in out_desired.items():
    if tid not in all_desired:
        all_desired[tid] = lab
    else:
        if all_desired[tid] != 'work' and lab=='work':
            all_desired[tid] = 'work'

# merge current label from either
all_current = dict(in_current)
for tid, lab in out_current.items():
    if tid not in all_current:
        all_current[tid] = lab

print('total_desired_threads', len(all_desired))
print('work_threads', sum(1 for v in all_desired.values() if v=='work'))
print('personal_threads', sum(1 for v in all_desired.values() if v=='personal'))

# show a sample of what we plan to label
sample_items = list(all_desired.items())[:10]
print('sample_plans', [(tid, lab, all_current.get(tid)) for tid, lab in sample_items])

